    "Studio попросит войти, когда откроется. Ещё нет аккаунта Roblox? Выбери {signUp} на экране входа в Studio. Genex никогда не видит твой пароль.",
  "Studio can reach this game's live saved data, so play tests here read and write what real players saved. To test without it, turn this off in Studio:":
    "Studio имеет доступ к настоящим сохранённым данным этой игры, поэтому тесты здесь читают и меняют то, что сохранили реальные игроки. Чтобы тестировать без них, выключи это в Studio:",
