  "That mcp add line names no server to add.": "В строке mcp add не указан сервер для добавления.",
  "That message hasn’t been answered yet.": "На это сообщение ещё нет ответа.",
  "That message is no longer in this chat.": "Этого сообщения больше нет в чате.",
