  "Too large to save, so it stays as it is: {names}.":
    "Файл слишком большой для сохранения и останется как есть: {names}.",
  "Too large to save, so they stay as they are: {names}.":
    "Файлы слишком большие для сохранения и останутся как есть: {names}.",
  "Too long": "Слишком длинный",
  "Too many accounts.": "Слишком много аккаунтов.",
  "Too many at once": "Слишком много за раз",
