  "Too many header names": "Слишком много имён заголовков",
  "Too short": "Слишком короткий",
  "Took a motion strip": "Снята серия кадров",
  "Took a picture of {asset}": "Сфотографирован {asset}",
  "Took a play-view shot": "Снят кадр из игры",
  "Took a screenshot": "Скриншот сделан",
  "Took a screenshot of the level": "Сделан скриншот уровня",
  "Took a still from {camera}": "Снят кадр с {camera}",
  Tool: "Инструмент",
  "Tool result": "Результат инструмента",
  Tools: "Инструменты",
  "Tools and connections for all your games.": "Инструменты и подключения для всех твоих игр.",
  "Tools for your agent: 3D, textures, animation, music, multiplayer.":
    "Инструменты для агента: 3D, текстуры, анимация, музыка, мультиплеер.",
  "Tools it routes": "Подключённые инструменты",
  "Tools the agents may call": "Инструменты, которые могут вызывать агенты",
  "Top creators": "Лучшие авторы",
  Tries: "Попытки",
  Trust: "Доверять",
  "Trust connector": "Доверять коннектору",
  "Trust this folder's Claude settings and hooks": "Доверять настройкам и хукам Claude из этой папки",
  Try: "Попробуй",
  "Try again": "Попробовать снова",
  "Try again in a few minutes.": "Попробуй снова через несколько минут.",
  "Try again in the game once the coin lands.": "Когда монеты поступят, попробуй снова в игре.",
  "Try again in the game. No coin was charged.": "Попробуй снова в игре. Монеты не списаны.",
  "Try again in the game. No coin was reserved or charged.":
    "Попробуй снова в игре. Монеты не зарезервированы и не списаны.",
  "Try again in the game. The coin went back to your balance.": "Попробуй снова в игре. Монеты вернулись на баланс.",
